const $ = (id) => document.getElementById(id);
const scenarios = {
  fee_mismatch:{expected:'₹12,48,500',variance:'− ₹18,720',processor:'Stripe India',amount:1872000,paymentId:'PAY-1042',reference:'STL-2026-0912-A',confidence:94,analysis:'The processor applied a 1.5% cross-border fee that is not present in the contracted domestic rate card. Settlement evidence, fee schedule, and batch totals reconcile to a single fee variance.',eligible:true,policy:'Within the ₹25,000 simulation ceiling. Reviewer approval is required and expires after 15 minutes.'},
  duplicate:{expected:'₹8,72,240',variance:'+ ₹8,72,240',processor:'Razorpay',amount:-87224000,paymentId:'PAY-1043',reference:'STL-2026-0912-B',confidence:98,analysis:'Two settlement rows share the same source payment, merchant reference, and processor trace. The later row is a probable duplicate and has been isolated from downstream reconciliation.',eligible:true,policy:'Duplicate evidence satisfies the simulation policy. A human reviewer must confirm the reversal proposal.'},
  high_value:{expected:'₹42,18,900',variance:'− ₹3,64,200',processor:'Adyen',amount:36420000,paymentId:'PAY-1044',reference:'STL-2026-0912-C',confidence:87,analysis:'A settlement reserve was applied above the configured tolerance. Evidence supports the cause, but the proposed adjustment exceeds the policy ceiling for this environment.',eligible:false,policy:'Policy blocks approval: ₹3,64,200 exceeds the ₹25,000 simulation ceiling. Escalation is required.'}
};
let liveApi=false,current=null,pendingDecision=null;
let demoCases=[makeCase('fee_mismatch','awaiting_approval','demo-case-1042'),makeCase('duplicate','awaiting_approval','demo-case-1043'),makeCase('high_value','expired','demo-case-1044')];
function makeCase(scenario,state='awaiting_approval',id=`demo-${Date.now()}`){const item=scenarios[scenario];return{id,scenario,state,eligible:item.eligible,currency:'INR',adjustment_minor:item.amount,version:1,analysis:item.analysis,confidence:item.confidence,ledger_entries:state==='approved'?1:0,evidence:{payment_id:item.paymentId,reference:item.reference},trace_id:`7f3a${Math.random().toString(16).slice(2,26).padEnd(24,'0')}`,timeline:[{agent:'Evidence agent',elapsed_ms:312,summary:'Retrieved settlement row, processor batch, and the active rate card through read-only MCP tools.'},{agent:'Reconciliation analyst',elapsed_ms:684,summary:item.analysis},{agent:'Policy specialist',elapsed_ms:241,summary:item.policy},{agent:'Proposal agent',elapsed_ms:178,summary:item.eligible?'Prepared a bounded simulated adjustment for reviewer decision.':'Stopped the proposal at the configured policy boundary.'}],audit:[{event:'investigation.created',actor:'operator',at:'2026-09-12T13:42:18Z'},{event:'evidence.retrieved',actor:'evidence-agent',at:'2026-09-12T13:42:19Z'},{event:'policy.evaluated',actor:'policy-specialist',at:'2026-09-12T13:42:20Z'}]}}
async function api(path,method='GET',body=null,review=false){const response=await fetch(path,{method,headers:{'Content-Type':'application/json',Authorization:`Bearer ${$(review?'reviewer':'operator').value}`},body:body?JSON.stringify(body):undefined});const type=response.headers.get('content-type')||'';if(!type.includes('application/json'))throw new Error('Live API is unavailable');const data=await response.json();if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));return data}
function formatAmount(minor,currency='INR'){if(minor===undefined)return'—';return new Intl.NumberFormat('en-IN',{style:'currency',currency,maximumFractionDigits:2}).format(minor/100)}
const statusLabel=(state)=>state.replaceAll('_',' ');
function show(c){current=c;$('empty').hidden=true;$('case').hidden=false;$('status').className=`case-status ${c.state}`;$('status').textContent=statusLabel(c.state);$('amount').textContent=formatAmount(c.adjustment_minor,c.currency);$('reference').textContent=c.evidence?`${c.evidence.payment_id} · ${c.evidence.reference}`:c.id;$('confidence').textContent=`${c.confidence||(c.eligible?94:78)}%`;$('analysis').textContent=c.analysis||c.error||'No findings available.';const scenario=scenarios[c.scenario];$('policy').textContent=c.state==='expired'?'This proposal expired and is permanently closed. Start a new investigation to obtain fresh evidence and policy.':c.state==='failed'?'The investigation failed safely. No simulated adjustment is available.':scenario?.policy||(c.eligible?'Within policy. Human approval is required.':'Policy blocks this proposal.');$('approve').disabled=c.state!=='awaiting_approval'||!c.eligible;$('reject').disabled=c.state!=='awaiting_approval';$('ledger').textContent=`Simulated ledger entries: ${c.ledger_entries||0} · Version ${c.version||1}`;$('trace-id').textContent=c.trace_id?`Trace ${c.trace_id.slice(0,10)}…`:'Trace unavailable';$('timeline').replaceChildren();for(const event of c.timeline||[]){const li=document.createElement('li'),title=document.createElement('strong'),time=document.createElement('time');title.textContent=event.agent;time.textContent=`${event.elapsed_ms} ms`;title.append(time);li.append(title,document.createTextNode(event.summary.slice(0,280)));$('timeline').append(li)}$('audit').textContent=JSON.stringify({case_id:c.id,trace_id:c.trace_id,version:c.version,audit:c.audit},null,2);renderHistory()}
function renderHistory(items=demoCases){$('history').replaceChildren();for(const item of items){const button=document.createElement('button'),row=document.createElement('div'),title=document.createElement('strong'),state=document.createElement('span'),meta=document.createElement('small');button.className=`history-item${current?.id===item.id?' selected':''}`;title.textContent=scenarios[item.scenario]?.paymentId||item.scenario.replaceAll('_',' ');state.textContent=statusLabel(item.state);row.append(title,state);meta.textContent=`${item.scenario.replaceAll('_',' ')} · ${formatAmount(item.adjustment_minor,item.currency)}`;button.append(row,meta);button.addEventListener('click',()=>show(item));$('history').append(button)}$('open-count').textContent=String(items.filter(item=>item.state==='awaiting_approval').length)}
async function loadHistory(){if(!liveApi){renderHistory();return}const cases=await api('/api/cases');demoCases=cases;renderHistory(cases)}
function updateScenarioPreview(){const item=scenarios[$('scenario').value];$('expected').textContent=item.expected;$('variance').textContent=item.variance;$('processor').textContent=item.processor}
$('scenario').addEventListener('change',updateScenarioPreview);
$('run').addEventListener('click',async()=>{$('run').disabled=true;$('message').textContent='Evidence, analysis, and policy agents are investigating…';try{let result;if(liveApi){result=await api('/api/cases','POST',{scenario:$('scenario').value})}else{await new Promise(resolve=>setTimeout(resolve,700));result=makeCase($('scenario').value);demoCases.unshift(result)}show(result);$('message').textContent=result.eligible?'Investigation complete. Review the evidence before deciding.':'Investigation stopped at the policy boundary.';await loadHistory()}catch(error){$('message').textContent=error.message}finally{$('run').disabled=false}});
function askDecision(decision){pendingDecision=decision;const approve=decision==='approve';$('dialog-title').textContent=approve?'Approve simulated adjustment?':'Reject this proposal?';$('dialog-copy').textContent=approve?'This records one simulated ledger entry for this exact case version. No real funds will move.':'The proposal will be closed with no ledger entry. The evidence and audit trail remain available.';$('dialog-confirm').textContent=approve?'Approve simulation':'Reject proposal';$('confirm-dialog').showModal()}
for(const decision of ['approve','reject'])$(decision).addEventListener('click',()=>askDecision(decision));
$('confirm-dialog').addEventListener('close',async()=>{if($('confirm-dialog').returnValue!=='confirm'||!pendingDecision||!current)return;const decision=pendingDecision;pendingDecision=null;$('approve').disabled=true;$('reject').disabled=true;try{let result;if(liveApi){result=await api(`/api/cases/${current.id}/decision`,'POST',{version:current.version,decision},true)}else{result={...current,state:decision==='approve'?'approved':'rejected',version:current.version+1,ledger_entries:decision==='approve'?1:0};demoCases=demoCases.map(item=>item.id===result.id?result:item)}show(result);$('message').textContent=decision==='approve'?'Simulation recorded. No real funds moved.':'Proposal rejected. No ledger entry was created.'}catch(error){$('message').textContent=error.message;if(liveApi)show(await api(`/api/cases/${current.id}`))}});
document.querySelectorAll('[data-jump]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(item=>item.classList.remove('active'));button.classList.add('active');document.getElementById(button.dataset.jump)?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('.rail').classList.remove('open')}));
$('menu-toggle').addEventListener('click',()=>{const open=document.querySelector('.rail').classList.toggle('open');$('menu-toggle').setAttribute('aria-expanded',String(open))});
async function boot(){updateScenarioPreview();try{const response=await fetch('/health',{headers:{Accept:'application/json'}}),type=response.headers.get('content-type')||'';if(!response.ok||!type.includes('application/json'))throw new Error('Demo');const health=await response.json();liveApi=true;$('mode').textContent=health.mode==='demo'?'Local demo runtime':'Gemini runtime';$('budget').textContent=health.mode==='demo'?'0 calls':'≤ 4 calls';$('budget-note').textContent=health.mode==='demo'?'Deterministic demo mode':'Per investigation ceiling'}catch{liveApi=false;$('mode').textContent='Interactive portfolio demo'}await loadHistory().catch(error=>{$('message').textContent=error.message;renderHistory()})}
function registerWebMcpTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController(),register=tool=>{try{void Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'select_synthetic_exception',title:'Select settlement exception',description:'Select one synthetic settlement exception and update the visible investigation inputs without starting a run.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:['fee_mismatch','duplicate','high_value']}},required:['scenario'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!scenarios[input.scenario])throw new Error('Unknown synthetic scenario');$('scenario').value=input.scenario;updateScenarioPreview();return{scenario:input.scenario,payment_id:scenarios[input.scenario].paymentId}}});register({name:'open_settlement_case',title:'Open settlement case',description:'Open an existing visible settlement case by its case id.',inputSchema:{type:'object',properties:{case_id:{type:'string',minLength:1}},required:['case_id'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){const item=demoCases.find(entry=>entry.id===input?.case_id);if(!item)throw new Error('Case not found');show(item);return{case_id:item.id,state:item.state,eligible:item.eligible}}});register({name:'start_synthetic_investigation',title:'Start synthetic investigation',description:'Start the currently selected synthetic settlement investigation and update the visible case workspace.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:['fee_mismatch','duplicate','high_value']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(input?.scenario){if(!scenarios[input.scenario])throw new Error('Unknown synthetic scenario');$('scenario').value=input.scenario;updateScenarioPreview()}$('run').click();while($('run').disabled)await new Promise(resolve=>setTimeout(resolve,100));if(!current)throw new Error('Investigation did not complete');return{case_id:current.id,state:current.state,eligible:current.eligible}}});register({name:'start_simulated_decision',title:'Review simulated decision',description:'Open the visible human confirmation dialog for approving or rejecting the selected simulated proposal. This does not confirm the decision.',inputSchema:{type:'object',properties:{decision:{type:'string',enum:['approve','reject']}},required:['decision'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!current)throw new Error('Select a case first');if(input?.decision==='approve'&&(!current.eligible||current.state!=='awaiting_approval'))throw new Error('This case cannot be approved');if(input?.decision==='reject'&&current.state!=='awaiting_approval')throw new Error('This case cannot be rejected');askDecision(input.decision);return{case_id:current.id,confirmation_open:true,decision:input.decision}}})}
boot();
registerWebMcpTools();
